theorem distS_eq (s : St) (who : Nat) (u : St) (he2 : distributeSupplierComp s who = some u) :
    accrualStart (s.acct who).supplierIndex s.supplyState.index ≤ s.supplyState.index ∧
    u = s.withAcct who fun a => { a with supplierIndex := s.supplyState.index, accrued := a.accrued + creditFor a.supply (accrualStart a.supplierIndex s.supplyState.index) s.supplyState.index }

theorem distB_eq (s : St) (who : Nat) (u : St) (he2 : distributeBorrowerComp s who = some u) :
    accrualStart (s.acct who).borrowerIndex s.borrowState.index ≤ s.borrowState.index ∧
    u = s.withAcct who fun a => { a with borrowerIndex := s.borrowState.index, accrued := a.accrued + creditFor a.borrow (accrualStart a.borrowerIndex s.borrowState.index) s.borrowState.index }

